		/// Determines whether the specified <see cref="DebitoBase"/> instances are considered equal using value semantics.
		///</summary>
		///<param name="Object1">The first <see cref="DebitoBase"/> to compare.</param>
		///<param name="Object2">The second <see cref="DebitoBase"/> to compare. </param>
		///<returns>true if Object1 is the same instance as Object2 or if both are null references or if objA.Equals(objB) returns true; otherwise, false.</returns>
		public static bool ValueEquals(DebitoBase Object1, DebitoBase Object2)
		{
			// both are null
			if (Object1 == null && Object2 == null)
				return true;

			// one or the other is null, but not both
			if (Object1 == null ^ Object2 == null)
				return false;
				
			bool equal = true;
			if (Object1.DebitoId != Object2.DebitoId)
				equal = false;
			if ( Object1.Fecha != null && Object2.Fecha != null )
			{
				if (Object1.Fecha != Object2.Fecha)
					equal = false;
			}
			else if (Object1.Fecha == null ^ Object2.Fecha == null )
			{
				equal = false;
			}
			if ( Object1.ClienteId != null && Object2.ClienteId != null )
			{
				if (Object1.ClienteId != Object2.ClienteId)
					equal = false;
			}
			else if (Object1.ClienteId == null ^ Object2.ClienteId == null )
			{
				equal = false;
			}
			if ( Object1.VendedorId != null && Object2.VendedorId != null )
			{
				if (Object1.VendedorId != Object2.VendedorId)
					equal = false;
			}
			else if (Object1.VendedorId == null ^ Object2.VendedorId == null )
			{
				equal = false;
			}
			if ( Object1.MontoDebito != null && Object2.MontoDebito != null )
			{
				if (Object1.MontoDebito != Object2.MontoDebito)
					equal = false;
			}
			else if (Object1.MontoDebito == null ^ Object2.MontoDebito == null )
			{
				equal = false;
			}
					
			return equal;
		}
		
